spectrum.input:
spinsys {
    channels 13C 1H
    nuclei 13C 1H
    shift 1 -4.736951571734001e-15p 80.0p 0.6000000000000002 29.999999999999993 49.99999999999997 70.00000000000003
    dipole 1 2 -4000.000000 0.000000 70.000000 140.000000
}

par {
    proton_frequency 400000000.0
    spin_rate 0
    start_operator I1x
    detect_operator I1p
    np 4096
    sw 100000.0
    crystal_file zcw28656
    gamma_angles 1
    verbose 0
}

proc pulseq {} {
    global par
    acq_block {
        delay [expr 1e6/$par(sw)]
    }
}

proc main {} {
    global par
    set f [fsimpson]
    faddlb $f 200.0 0
    fft $f
    fsave $f spectrum.spe -xreim
}

